@php
    $control = 'mt-2 block h-10 w-full rounded-xl border-slate-300 bg-white px-3 text-sm text-slate-800 shadow-sm focus:border-indigo-500 focus:ring-indigo-500';
    $toggle = 'h-5 w-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500';
    $background = match ((string) data_get($config, 'sidebar.presentation.background', 'theme')) {
        'system', 'white' => 'light',
        default => (string) data_get($config, 'sidebar.presentation.background', 'theme'),
    };
    $customBackground = (string) data_get($config, 'sidebar.presentation.custom_background', '#0f172a');
    $customAccent = (string) data_get($config, 'sidebar.presentation.custom_accent', '#4f46e5');
    $widthToPx = static function (mixed $value, int $fallback): int {
        if (is_numeric($value)) return (int) $value;
        $value = trim((string) $value);
        if (preg_match('/^(\d+(?:\.\d+)?)px$/', $value, $matches)) return (int) round((float) $matches[1]);
        if (preg_match('/^(\d+(?:\.\d+)?)rem$/', $value, $matches)) return (int) round((float) $matches[1] * 16);
        return $fallback;
    };
    $expandedWidthPx = max(224, min(384, $widthToPx(data_get($config, 'sidebar.expanded_width'), 256)));
    $collapsedWidthPx = max(64, min(112, $widthToPx(data_get($config, 'sidebar.collapsed_width'), 80)));
@endphp

