        isDark(hex) { hex = this.validHex(hex, '#ffffff').slice(1); const r=parseInt(hex.slice(0,2),16),g=parseInt(hex.slice(2,4),16),b=parseInt(hex.slice(4,6),16); return ((0.2126*r+0.7152*g+0.0722*b)/255)<.56; },
        bg() { return this.sidebarBackground==='dark'?'#020617':this.sidebarBackground==='custom'?this.validHex(this.customBackground,'#0f172a'):this.sidebarBackground==='light'?'#ffffff':'#eef2ff'; },
        accent() { return this.sidebarBackground==='custom'?this.validHex(this.customAccent,'#4f46e5'):'#4f46e5'; },
        text() { return this.isDark(this.bg())?'#f8fafc':'#0f172a'; }, secondary() { return this.isDark(this.bg())?'#cbd5e1':'#475569'; }, muted() { return this.isDark(this.bg())?'#94a3b8':'#64748b'; }, soft() { return this.isDark(this.bg())?'rgba(255,255,255,.075)':'rgba(15,23,42,.055)'; }, border() { return this.isDark(this.bg())?'rgba(255,255,255,.13)':'rgba(15,23,42,.10)'; }, activeText() { return this.isDark(this.accent())?'#ffffff':'#0f172a'; }
    }">
